 DerbyMatch m;int errors;string folder,key,saved;bool had,restored,hardOnly;readonly StringBuilder log=new StringBuilder();void Check(bool ok,string message){log.AppendLine((ok?"PASS ":"FAIL ")+message);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert){errors++;log.AppendLine("ERROR "+message);File.WriteAllText(folder+"/progress.txt",log.ToString());}}void Awake(){hardOnly=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsDerbyHard")>=0;
