 IEnumerator Start(){Check(DerbyFixtures.Run()>750,"localized damage, effective mass, rear protection, capped impact, five-second real movement, draw, lock, first-three and reset rule fixtures");yield return SportsProbeScene.Ensure<DerbyMatch>("TruckDemolitionDerby");m=FindAnyObjectByType<DerbyMatch>();yield return null;key=m.PreferenceKey;had=SportsPrefs.HasKey(key);saved=SportsPrefs.GetString(key);for(int test=hardOnly?2:0;test<3&&errors==0;test++){m.SetupScreen();m.setup.count=test==0?2:8;m.option=1;m.NormalizeSetup();m.AllBots();for(int i=0;i<m.setup.count;i++)m.setup.players[i].difficulty=(BowlingDifficulty)test;Check(m.StartMatch(),"actual full NWH Derby series starts difficulty="+test+" trucks="+m.setup.count);bool outward=true;for(int s=0;s<m.setup.count;s++){var f=m.fighters[s];outward&=Vector3.Dot(f.transform.forward,Vector3.ProjectOnPlane(f.body.position,Vector3.up).normalized)>.99f&&f.body.linearVelocity==Vector3.zero;}Check(outward,"every heat begins stationary with engines outward and protected rears toward center");Time.timeScale=5;float end=Time.realtimeSinceStartup+2400,next=0,peakSpeed=0,peakRoll=0;bool paused=false,replayed=false;bool verifiedScaling=false;int maxDamaged=0,diagnosedHeat=-1;while(!m.Finished&&Time.realtimeSinceStartup<end&&errors<10){for(int i=0;i<m.setup.count;i++){peakSpeed=Mathf.Max(peakSpeed,m.fighters[i].body.linearVelocity.magnitude);peakRoll=Mathf.Max(peakRoll,Vector3.Angle(m.fighters[i].transform.up,Vector3.up));maxDamaged=Mathf.Max(maxDamaged,m.fighters[i].damage.Hits);var f=m.fighters[i];if(f.QualifyingContacts>0){verifiedScaling|=f.LastBaseDamage>0&&Mathf.Abs(f.LastAppliedDamage-DerbyDamageState.ScaleContact(f.LastBaseDamage,m.derbyDamageMultiplier))<.00001f;}}replayed|=m.Stage==DerbyStage.Replay&&m.replay.Playing;if(!paused&&m.Stage==DerbyStage.Playing&&m.Clock>2){m.Pause();var p=m.fighters[0].body.position;float stop=m.fighters[0].motion.Stopped;int hits=m.Hits;yield return new WaitForSecondsRealtime(.2f);Check(p==m.fighters[0].body.position&&stop==m.fighters[0].motion.Stopped&&hits==m.Hits,"pause preserves actual chassis, inactivity clock and damage");m.Resume();Time.timeScale=5;paused=true;}if(m.Stage==DerbyStage.Playing&&m.Clock>3.5f&&diagnosedHeat!=m.rules.Heat){diagnosedHeat=m.rules.Heat;for(int stateSlot=0;stateSlot<m.setup.count;stateSlot++)log.AppendLine("RESET_STATE heat="+m.rules.Heat+" clock="+m.Clock+" "+VehicleState(m.fighters[stateSlot]));if(m.rules.Heat>3){bool allSpawnedStill=true;for(int k=0;k<m.setup.count;k++){float a=k*Mathf.PI*2/m.setup.count;var spawn=new Vector3(Mathf.Sin(a)*29,0,Mathf.Cos(a)*29);allSpawnedStill&=Vector3.ProjectOnPlane(m.fighters[k].body.position-spawn,Vector3.up).magnitude<.5f;}Check(!allSpawnedStill,"fresh all-AI heat departs its unobstructed starting positions; heat="+m.rules.Heat);if(allSpawnedStill)break;}}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"LIVE difficulty="+test+" heat="+m.rules.Heat+" stage="+m.Stage+" clock="+m.Clock+" wins="+string.Join(",",m.rules.wins)+" remaining="+m.rules.Remaining+" hits="+m.Hits+" explosions="+m.Explosions+" draws="+m.Draws);next=Time.realtimeSinceStartup+3;}yield return null;}if(m.Finished)yield return SportsResultsAcceptance.Capture(m,Check,folder+"/difficulty-"+test,slot=>SportsResultPlacings.FromFinalTotals(slot,m.setup.count,m.rules.wins,m.rules.Winner),slot=>(double?)m.rules.wins[slot],slot=>m.rules.Winner==slot);
 Check(m.Finished&&m.rules.Winner>=0&&m.rules.wins[m.rules.Winner]==3,"complete physical first-to-three Derby match difficulty="+test);Check(m.Hits>0&&m.Explosions>0&&maxDamaged>0&&peakSpeed>3&&replayed&&verifiedScaling,"actual NWH drive, energetic impacts, local damage and recorded physical elimination occur");log.AppendLine("MATCH difficulty="+test+" winner="+m.rules.Winner+" heats="+m.rules.Heat+" wins="+string.Join(",",m.rules.wins)+" hits="+m.Hits+" explosions="+m.Explosions+" draws="+m.Draws+" peakIncomingNormal="+m.PeakImpact+" peakSpeed="+peakSpeed+" peakRoll="+peakRoll+" maxDamageEventsOnTruck="+maxDamaged);Time.timeScale=1;m.SetupScreen();}if(errors==0){m.setup.count=8;m.NormalizeSetup();m.AllBots();Check(m.StartMatch(),"rematch starts");bool clean=true;for(int i=0;i<8;i++){var f=m.fighters[i];clean&=f.damage.Structure==0&&f.damage.Engine==0&&f.vehicle.powertrain.engine.Damage==0&&f.motion.Stopped==0&&!f.Eliminated&&!f.fragments.Bursting;}Check(clean&&m.rules.Heat==1&&m.Hits==0&&m.Explosions==0,"rematch restores all damage/powertrain/fragments/inactivity and scores");m.SetupScreen();}Restore();log.AppendLine("ERRORS="+errors+". Separate pure rule fixtures and actual native NWH/PhysX full autonomous matches. No injected scores/outcomes, human/hardware, Windows or rendered-performance claim.");File.WriteAllText(folder+"/result.txt",log.ToString());
